// src/util/curveLength.ts
var ABSCISSAE = [
  0.1834346424956498,
  0.525532409916329,
  0.7966664774136267,
  0.9602898564975363
];
var WEIGHTS = [
  0.362683783378362,
  0.3137066458778873,
  0.2223810344533745,
  0.1012285362903763
];
var TOLERANCE = 1e-10;
var MAX_DEPTH = 40;
function speedOf(c, scaleX, scaleY) {
  const ax = 3 * (c.cx0 - c.x0) * scaleX;
  const bx = 3 * (c.cx1 - c.cx0) * scaleX;
  const dx = 3 * (c.x1 - c.cx1) * scaleX;
  const ay = 3 * (c.cy0 - c.y0) * scaleY;
  const by = 3 * (c.cy1 - c.cy0) * scaleY;
  const dy = 3 * (c.y1 - c.cy1) * scaleY;
  return (t) => {
    const u = 1 - t;
    const a = u * u;
    const b = 2 * u * t;
    const d = t * t;
    return Math.hypot(a * ax + b * bx + d * dx, a * ay + b * by + d * dy);
  };
}
function gaussLegendre(speed, from, to) {
  const half = (to - from) / 2;
  const mid = (from + to) / 2;
  let sum = 0;
  for (let i = 0; i < ABSCISSAE.length; i++) {
    const x = half * ABSCISSAE[i];
    sum += WEIGHTS[i] * (speed(mid - x) + speed(mid + x));
  }
  return sum * half;
}
function adaptive(speed, from, to, whole, tolerance, depth) {
  const mid = (from + to) / 2;
  const left = gaussLegendre(speed, from, mid);
  const right = gaussLegendre(speed, mid, to);
  return depth >= MAX_DEPTH || !(Math.abs(left + right - whole) > tolerance) ? left + right : adaptive(speed, from, mid, left, tolerance / 2, depth + 1) + adaptive(speed, mid, to, right, tolerance / 2, depth + 1);
}
function cubicLengthPx(c, scaleX, scaleY) {
  const leg = (x0, y0, x1, y1) => Math.hypot((x1 - x0) * scaleX, (y1 - y0) * scaleY);
  const polygon = leg(c.x0, c.y0, c.cx0, c.cy0) + leg(c.cx0, c.cy0, c.cx1, c.cy1) + leg(c.cx1, c.cy1, c.x1, c.y1);
  const speed = speedOf(c, scaleX, scaleY);
  return adaptive(
    speed,
    0,
    1,
    gaussLegendre(speed, 0, 1),
    TOLERANCE * polygon,
    0
  );
}

export {
  cubicLengthPx
};
