// src/overlayLabels.ts
var LABEL_PX = 11;
var LABEL_CHAR_PX = 6.2;
var LABEL_PAD = 4;
function labelWidth(text) {
  return text.length * LABEL_CHAR_PX + LABEL_PAD * 2;
}
function overlaps(a, b) {
  return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
}
function offFrame(box, frame) {
  return box.x1 <= 0 || box.x0 >= frame.width || box.y1 <= 0 || box.y0 >= frame.height;
}
function insideFrame(box, frame) {
  return box.x0 >= 0 && box.x1 <= frame.width && box.y0 >= 0 && box.y1 <= frame.height;
}
function grown(box, by) {
  return {
    x0: box.x0 - by,
    x1: box.x1 + by,
    y0: box.y0 - by,
    y1: box.y1 + by
  };
}
function occupancy(frame, reserved = []) {
  const placed = [...reserved];
  return (box, path) => {
    const taken = path ? [box, path] : [box];
    if (offFrame(box, frame) || placed.some((p) => taken.some((t) => overlaps(p, t)))) {
      return false;
    }
    for (const t of taken) {
      placed.push(t);
    }
    return true;
  };
}
var SLIDE_STEP_PX = 8;
function slides(slide) {
  const out = [0];
  for (let d = SLIDE_STEP_PX; d < slide; d += SLIDE_STEP_PX) {
    out.push(-d, d);
  }
  if (slide > 0) {
    out.push(-slide, slide);
  }
  return out;
}
function placeLabels(candidates, frame, take, reserved = [], leaders = 0) {
  const out = [];
  let apart = 0;
  const row = LABEL_PX + LABEL_PAD * 2;
  const boxAt = (x, y, w) => ({
    x0: x - w / 2,
    x1: x + w / 2,
    y0: y - LABEL_PX - LABEL_PAD,
    y1: y + LABEL_PAD
  });
  const stackFrom = (c, text, from, direction) => {
    const w = labelWidth(text);
    const spots = [];
    for (let tries = 0; tries <= (c.stack ?? 0); tries++) {
      const y = from + direction * tries * row;
      if (offFrame(boxAt(c.x, y, w), frame)) {
        break;
      }
      for (const dx of slides(c.slide ?? 0)) {
        spots.push({ dx, y, distance: Math.hypot(dx, tries * row) });
      }
    }
    spots.sort((a, b) => a.distance - b.distance);
    let crowded = false;
    for (const { dx, y } of spots) {
      const box = boxAt(c.x + dx, y, w);
      if (insideFrame(box, frame) && (c.fits?.(box) ?? true)) {
        if (take(box)) {
          return { placed: { ...c, x: c.x + dx, text, y, w }, crowded };
        }
        crowded ||= !reserved.some((r) => overlaps(r, box));
      }
    }
    return { placed: void 0, crowded };
  };
  const place = (c, text) => {
    const first = stackFrom(c, text, c.y, c.y > frame.height / 2 ? -1 : 1);
    return first.placed || c.flipY === void 0 || first.crowded ? first : stackFrom(c, text, c.flipY, c.flipY < c.y ? -1 : 1);
  };
  const rows = Math.ceil(frame.height / row);
  const offsetsWithin = (slide) => {
    const offsets = [];
    for (let k = -rows; k <= rows; k++) {
      for (const dx of slides(slide)) {
        offsets.push({ dx, dy: k * row, distance: Math.hypot(dx, k * row) });
      }
    }
    return offsets.sort((a, b) => a.distance - b.distance);
  };
  let acrossPane;
  const nearestFree = (c, text, from) => {
    const w = labelWidth(text);
    const offsets = insideFrame(
      { x0: from.x, x1: from.x, y0: from.y, y1: from.y },
      frame
    ) ? acrossPane ??= offsetsWithin(frame.width) : offsetsWithin(c.slide ?? 0);
    const firstSpot = (stands) => {
      let spot2;
      for (let i = 0; i < offsets.length && !spot2; i++) {
        const x = from.x + offsets[i].dx;
        const y = from.y + offsets[i].dy;
        const box = boxAt(x, y, w);
        spot2 = insideFrame(box, frame) && stands(box) ? { x, y } : void 0;
      }
      return spot2;
    };
    const spot = firstSpot((box) => (c.fits?.(box) ?? true) && take(box)) ?? firstSpot(take);
    return spot && { ...c, x: spot.x, y: spot.y, text, w };
  };
  for (const c of candidates) {
    const full = place(c, c.text);
    const short = full.placed || c.fallback === void 0 ? void 0 : place(c, c.fallback);
    const stacked = full.placed ?? short?.placed;
    const crowded = full.crowded || short?.crowded === true;
    const led = stacked || c.nearest === void 0 || crowded && apart >= leaders ? void 0 : nearestFree(c, c.text, c.nearest);
    if (led) {
      apart++;
    }
    const placed = stacked ?? led;
    if (placed) {
      out.push(placed);
    }
  }
  return out;
}

export {
  LABEL_PX,
  LABEL_CHAR_PX,
  LABEL_PAD,
  labelWidth,
  overlaps,
  insideFrame,
  grown,
  occupancy,
  placeLabels
};
